        next[i] = i + 1;
    }

    next[25] = 0;

    int s = k - 1;
    for (int i = n - 1; i >= 0; i--) {
        result[i] = (char)('a' + s % 26);
        s = s / 26;
    }

    while (s > 0) {
        int x = s % 26;
        if (x == 0) x = 26;
        s = s / 26 - 1;
        char c = (char)('a' + x - 1);
        for (int i = 0; i < 26; i++) {
            if (next[i] == x) {
                c = (char)('a' + i);
                break;
            }
        }
        result[0] = c;
        for (int i = 1; i < n; i++) {
            result[i] = (char)('a' + (result[i - 1] - 'a' + 1) % 26);
        }
        s -= next[c - 'a'];
    }

    return new String(result);
}

